mapper.select:
SELECT exam.id, exam_name, paper.name as paperName, start_time, duration, exam.status, exam.creator_id, exam.create_time, exam.update_time FROM exam left join paper on exam.paper_id = paper.id ${ew.customSqlSegment}
AND exam.status = 1 AND #{now} < exam.start_time
AND exam.status = 1 AND #{now} >= exam.start_time AND #{now} <= DATE_ADD(exam.start_time, INTERVAL exam.duration MINUTE)
AND exam.status = 1 AND #{now} > DATE_ADD(exam.start_time, INTERVAL exam.duration MINUTE)
AND exam.status = #{viewStatus.code}
ORDER BY exam.update_time DESC

select e.id, e.exam_name, e.status, e.duration, e.start_time, e.paper_id from exam e WHERE ( EXISTS ( SELECT 1 FROM exam_student es WHERE es.exam_id = e.id AND es.student_id = #{stuId} ) OR EXISTS ( SELECT 1 FROM exam_class ec INNER JOIN sys_user u ON u.class_id = ec.class_id WHERE ec.exam_id = e.id AND u.id = #{stuId} ) ) ${ew.customSqlSegment}
AND e.status = 1 AND #{now} < e.start_time
AND e.status = 1 AND #{now} >= e.start_time AND #{now} <= DATE_ADD(e.start_time, INTERVAL e.duration MINUTE)
AND e.status = 1 AND #{now} > DATE_ADD(e.start_time, INTERVAL e.duration MINUTE)
AND e.status = #{viewStatus.code}
